test('service worker precaches every linked asset and preserves data vault on activation',async()=>{const handlers={},deleted=[],added=[];const cache={addAll:async xs=>added.push(...xs),match:async()=>undefined,put:async()=>{}};const context=vm.createContext({URL,Request,Response,Set,self:{location:{origin:'https://test.invalid'},registration:{scope:'https://test.invalid/Tracker/'},clients:{claim:async()=>{}},skipWaiting:async()=>{},addEventListener:(e,f)=>handlers[e]=f},caches:{open:async()=>cache,keys:async()=>['my-rhythm-v-old','life-tracker-app-old','my-rhythm-data-vault-v1','unrelated'],delete:async k=>deleted.push(k)},fetch:async()=>new Response('network')});vm.runInContext(fs.readFileSync(path.join(root,'sw.js'),'utf8'),context);let pending;handlers.install({waitUntil:p=>pending=p});await pending;for(const req of added){const local=new URL(req.url).pathname.replace('/Tracker/','');assert.ok(fs.existsSync(path.join(root,local||'index.html')),local)}const html=fs.readFileSync(path.join(root,'index.html'),'utf8');for(const [,src] of html.matchAll(/(?:src|href)="([^"#]+\.(?:js|css)(?:\?[^"]*)?)"/g))assert.ok(added.some(r=>new URL(r.url).pathname.endsWith(src.split('?')[0])),src);handlers.activate({waitUntil:p=>pending=p});await pending;assert.deepEqual(deleted,['my-rhythm-v-old','life-tracker-app-old']);let responded=false;handlers.fetch({request:new Request('https://test.invalid/Tracker/__my_rhythm_data_vault_v1__.json'),respondWith(){responded=true}});assert.equal(responded,false);cache.match=async()=>new Response('offline');context.fetch=async()=>{throw Error('offline')};handlers.fetch({request:new Request('https://test.invalid/Tracker/app.js?v=6112'),respondWith:p=>pending=p});assert.equal(await (await pending).text(),'offline');context.fetch=async()=>new Response('error',{status:500});handlers.fetch({request:new Request('https://test.invalid/Tracker/app.js?v=6112'),respondWith:p=>pending=p});assert.equal(await (await pending).text(),'offline');});
