function food(id,date='2024-01-02',protein=12){return {id,date,meal:'breakfast',name:'Synthetic food',portion:{amount:100,unit:'g'},source:'label',nutrients:{calories:{value:250,unit:'kcal',quality:'label'},protein:{value:protein,unit:'g',quality:'label'}}}}
function nutritionPayload(...entries){return {format:'my-rhythm-nutrition-import-v1',entries}}
test('nutrition fresh install, legacy migration and backups keep separate food data',()=>{
 const r=runtime();assert.deepEqual(r.json('data.nutrition'),{entries:[],goals:{}});r.ctx.f=fixture();r.ctx.f.nutrition={entries:[food('persisted')],goals:{calories:2000}};
 const migrated=r.json('migrateData(f)');assert.deepEqual(migrated.nutrition,r.ctx.f.nutrition);assert.deepEqual(r.json('validateBackupObject({format:"my-life-tracker-backup",data:f}).nutrition'),r.ctx.f.nutrition);
 assert.throws(()=>{r.ctx.bad={...r.ctx.f,nutrition:{entries:'wrong'}};r.run('validateBackupObject(bad)')});
});
test('food import is previewed, additive, idempotent and conflict updates need opt-in',()=>{
 const r=runtime();r.run('persistData=()=>{}');r.ctx.p=nutritionPayload(food('one'),food('two','2024-01-03',5));
 r.run('var entries=nutritionValidateImport(p);var preview=nutritionPreview(entries)');assert.deepEqual(r.json('preview.map(x=>x.action)'),['add','add']);
 assert.deepEqual(r.json('nutritionApplyImport(preview)'),{added:2,updated:0,skipped:0});assert.equal(r.run('data.nutrition.entries.length'),2);
 r.run('preview=nutritionPreview(nutritionValidateImport(p))');assert.deepEqual(r.json('preview.map(x=>x.action)'),['skip','skip']);assert.equal(r.json('nutritionApplyImport(preview)').skipped,2);
 r.ctx.revised=nutritionPayload(food('one','2024-01-02',20));r.run('preview=nutritionPreview(nutritionValidateImport(revised))');assert.equal(r.run('preview[0].action'),'conflict');r.run('nutritionApplyImport(preview)');assert.equal(r.run('data.nutrition.entries[0].nutrients.protein.value'),12);
 r.run('nutritionApplyImport(preview,{replaceConflicts:true})');assert.equal(r.run('data.nutrition.entries[0].nutrients.protein.value'),20);
 r.ctx.dupe=nutritionPayload(food('different-id','2024-01-02',20));r.run('preview=nutritionPreview(nutritionValidateImport(dupe))');assert.equal(r.run('preview[0].action'),'add');
 assert.deepEqual(r.json('data.logs'),{});
});
test('a stale import preview cannot overwrite intervening changes',()=>{
 const r=runtime();r.run('persistData=()=>{}');r.ctx.p=nutritionPayload(food('one'));r.run('var preview=nutritionPreview(nutritionValidateImport(p));data.nutrition.entries.push(nutritionNormalizeRecord('+JSON.stringify(food('one'))+'))');assert.throws(()=>r.run('nutritionApplyImport(preview)'),/changed since preview/);
});
test('nutrient units, unknowns, true zero, partial totals and incompatible vitamin bases',()=>{
 const r=runtime();r.ctx.p=nutritionPayload({...food('aa'),nutrients:{calories:{value:418.4,unit:'kJ',quality:'estimated'},protein:{value:12000,unit:'mg',quality:'label'},vitaminA:{value:500,unit:'ug',quality:'label',basis:'RAE'}}},{...food('bb'),nutrients:{protein:{value:null,quality:'unknown'},vitaminA:{value:0,unit:'µg',quality:'label',basis:'retinol'}}});
 r.run('data.nutrition.entries=nutritionValidateImport(p)');assert.ok(Math.abs(r.run('nutritionAggregate("2024-01-02").calories.value')-100)<1e-9);assert.equal(r.run('nutritionAggregate("2024-01-02").protein.value'),12);assert.equal(r.run('nutritionAggregate("2024-01-02").protein.partial'),true);assert.equal(r.run('nutritionAggregate("2024-01-02").vitaminA.value'),null);assert.equal(r.run('nutritionAggregate("2024-01-02").vitaminA.mixedBasis'),true);
 assert.deepEqual(r.json('nutritionEffectiveProtein("2024-01-02")'),{value:12,source:'foods',partial:true,manual:null});r.run('data.logs["2024-01-02"]={protein:0}');assert.equal(r.run('nutritionEffectiveProtein("2024-01-02").value'),0);assert.equal(r.run('nutritionEffectiveProtein("2024-01-02").source'),'manual');
});
